solution.solution.cpp:
unsigned int setBit(unsigned int flags, int bit)
{
    return flags | (1u << bit);
}

unsigned int clearBit(unsigned int flags, int bit)
{
    return flags & ~(1u << bit);
}

unsigned int toggleBit(unsigned int flags, int bit)
{
    return flags ^ (1u << bit);
}

bool testBit(unsigned int flags, int bit)
{
    return (flags & (1u << bit)) != 0;
}

unitTests:
TEST("setBit switches a bit on") { CHECK_EQ(setBit(0b0000u, 2), 0b0100u); CHECK_EQ(setBit(0b0100u, 2), 0b0100u); }
TEST("clearBit switches a bit off") { CHECK_EQ(clearBit(0b1111u, 1), 0b1101u); CHECK_EQ(clearBit(0b1000u, 1), 0b1000u); }
TEST("toggleBit flips a bit") { CHECK_EQ(toggleBit(0b0101u, 0), 0b0100u); CHECK_EQ(toggleBit(0b0101u, 1), 0b0111u); }
TEST("testBit reads a bit") { CHECK(testBit(0b0100u, 2)); CHECK(!testBit(0b0100u, 1)); }

